"""Invoices for Priya's studio: rates, line totals and a rendered invoice.

House rules, kept by the tests in tests/ and audited by check.py:

* Money is rounded half up to two decimals. Not with round(), which rounds half
  to even: round(2.675, 2) is 2.67 where the accountant expects 2.68.
* Billable time rounds up to the next six-minute block, so 61 minutes bills as
  1.1 hours, not 1.0166.
* A line marked nonbillable is still shown on the invoice but adds nothing to
  any total.
* An unknown rate code raises UnknownRate, never KeyError.
* Long-standing clients get ten percent off codes in LOYALTY.

A line is a dict: date, task, code, minutes, and optionally nonbillable.
Pasted rows like "2026-09-21 dev 185 landing page" are turned into dicts by
parse_line(); render_invoice accepts both dicts and such raw rows.
"""

from decimal import ROUND_HALF_UP, Decimal

RATES = {"dev": 92.25, "review": 68.25, "admin": 43.50}

LOYALTY = {"review"}


class UnknownRate(Exception):
    pass


def money(amount):
    """Round half up to two decimals."""
    return float(Decimal(str(amount)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def billable_hours(minutes):
    """Minutes as hours, rounded up to the next six-minute block."""
    return -(-int(minutes) // 6) / 10


def rate_for(code):
    if code not in RATES:
        raise UnknownRate(code)
    rate = RATES[code]
    if code in LOYALTY:
        rate = money(rate * 0.9)
    return rate


def estimate(minutes, code):
    """What a block of work would cost, without a full line: billable hours
    at the rate for code, rounded through money()."""
    return money(billable_hours(minutes) * rate_for(code))


def as_line(row):
    """A pasted row like '2026-09-21 dev 185 landing page' as a line dict.
    Rows that are already dicts pass through unchanged."""
    if isinstance(row, dict):
        return row
    return parse_line(row)


def parse_line(text):
    """Turn one pasted row 'date code minutes task' into a line dict, raising
    ValueError on anything that is not such a row."""
    if not isinstance(text, str):
        raise ValueError(f"parse_line expects text, got {type(text).__name__}")
    parts = text.split(None, 3)
    if len(parts) != 4:
        raise ValueError(f"cannot parse line: {text!r}")
    date, code, minutes_text, task = parts
    try:
        minutes = int(minutes_text)
    except ValueError:
        raise ValueError(f"minutes must be a whole number: {minutes_text!r}") from None
    if not date or not code or not task:
        raise ValueError(f"cannot parse line: {text!r}")
    return {"date": date, "task": task, "code": code, "minutes": minutes}


def line_total(line):
    return money(billable_hours(line["minutes"]) * rate_for(line["code"]))


def day_total(lines, date):
    """What we bill for one date: the sum of the billable lines that day."""
    return money(sum(line_total(l) for l in lines if l["date"] == date and not l.get("nonbillable")))


def invoice_total(lines):
    return money(sum(line_total(l) for l in lines if not l.get("nonbillable")))


def render_line(line):
    mark = " (nonbillable)" if line.get("nonbillable") else ""
    return f"{line['task']}\t{billable_hours(line['minutes']):.1f}h\t{line_total(line):.2f}{mark}"


def render_invoice(lines):
    """The whole invoice as one string: every line, then the TOTAL row.
    Lines may be dicts or pasted rows, via as_line()."""
    body = "\n".join(render_line(as_line(l)) for l in lines)
    return f"{body}\nTOTAL\t\t{invoice_total([as_line(l) for l in lines]):.2f}"


def summary(lines):
    """Billable hours per task name, every line counted, nonbillable included."""
    totals = {}
    for line in lines:
        task = line["task"]
        totals[task] = money(totals.get(task, 0) + billable_hours(line["minutes"]))
    return totals

